import type {KeyboardEvent, MouseEvent, ReactNode} from 'react';
import React, {memo, useCallback, useMemo} from 'react';

import {Check, ChevronRight, Pin, PinSlash} from '@gravity-ui/icons';
import type {ButtonButtonProps} from '@gravity-ui/uikit';
import {Button, Icon, Tooltip} from '@gravity-ui/uikit';

import {cnTrackerSelect} from '../TrackerSelect.classname';
import {useHint} from '../hooks/useHint';
import type {
    TrackerSelectItem,
    TrackerSelectItemActions,
    TrackerSelectItemValueBase,
} from '../types';
import {getElementId} from '../utils/getElementId';

export type SelectItemProps<Value extends TrackerSelectItemValueBase = TrackerSelectItemValueBase> =
    {
        item: TrackerSelectItem<Value>;
        view?: 'meta-primary';
        isSelected?: boolean;
        isDisabled?: boolean;
        active?: boolean;
        showMeta?: boolean;
        showArrowOnUnselectedItems?: boolean;
        hideCheckbox?: boolean;
        singleSelect?: boolean;
        renderItem?: (item: TrackerSelectItem<Value>, isSelected: boolean) => ReactNode;
        renderInfo?: (item: TrackerSelectItem<Value>, isSelected: boolean) => ReactNode;
        groupId?: string;
        onPin?: (id: string) => void;
        onUnpin?: (id: string) => void;
        itemActions?: TrackerSelectItemActions<Value> | null;
        pinnable?: boolean;
        disableDefaultItemRender?: boolean;
        onItemClick?: (item: TrackerSelectItem<Value>) => void;
        itemClassName?: string;
    };

const SelectItemWrapped = <Value extends TrackerSelectItemValueBase>({
    item,
    view,
    isSelected,
    isDisabled,
    active,
    itemActions: ItemActions,
    showMeta,
    showArrowOnUnselectedItems,
    hideCheckbox,
    renderItem,
    renderInfo,
    pinnable,
    onPin,
    onUnpin,
    groupId,
    disableDefaultItemRender,
    onItemClick,
    itemClassName,
}: SelectItemProps<Value>) => {
    const {withHint, handleTextNodeRef} = useHint();

    const handleClick = useCallback(
        (_event: MouseEvent<HTMLDivElement>) => {
            if (isDisabled) {
                return;
            }

            onItemClick?.(item);
        },
        [isDisabled, item, onItemClick],
    );

    const handleKeyDown = useCallback(
        (event: KeyboardEvent<HTMLDivElement>) => {
            if (isDisabled) {
                return;
            }

            if (event.key === 'Enter' || event.key === ' ') {
                event.preventDefault();
                onItemClick?.(item);
            }
        },
        [isDisabled, item, onItemClick],
    );

    const handlePinClick = useCallback<NonNullable<ButtonButtonProps['onClick']>>(
        (event: MouseEvent<HTMLButtonElement>) => {
            event.stopPropagation();
            if (item.pinned) {
                onUnpin?.(item.id);
            } else {
                onPin?.(item.id);
            }
        },
        [item.pinned, item.id, onPin, onUnpin],
    );

    const withMeta = showMeta && Boolean(item.meta);

    const icon = useMemo(() => {
        if (hideCheckbox) {
            return null;
        }

        if (isSelected) {
            return (
                <Icon
                    className={cnTrackerSelect('checkbox-icon', {type: 'checkbox'})}
                    data={Check}
                    size={16}
                />
            );
        }

        if (showArrowOnUnselectedItems) {
            return (
                <Icon
                    className={cnTrackerSelect('checkbox-icon', {type: 'arrow'})}
                    data={ChevronRight}
                    size={16}
                />
            );
        }

        return <span className={cnTrackerSelect('checkbox-spacer')} />;
    }, [hideCheckbox, isSelected, showArrowOnUnselectedItems]);

    const itemId = getElementId(item.id, groupId);

    return (
        <Tooltip
            content={item.display}
            placement={['right', 'bottom-end']}
            closeDelay={0}
            openDelay={500}
            disabled={!withHint}
        >
            <div
                id={itemId}
                data-id={`item-${groupId}-${item.id}`}
                className={cnTrackerSelect(
                    'list-item',
                    {
                        disabled: isDisabled,
                        active,
                        view: view === 'meta-primary' ? withMeta && view : view,
                        selected: isSelected,
                        pinned: item.pinned,
                    },
                    itemClassName,
                )}
                style={{position: 'relative'}}
            >
                <div
                    role="button"
                    onClick={handleClick}
                    onKeyDown={handleKeyDown}
                    tabIndex={0}
                    className={cnTrackerSelect('list-item-wrapper')}
                    aria-pressed={isSelected}
                    aria-disabled={isDisabled}
                >
                    {!disableDefaultItemRender && icon}
                    {renderItem?.(item, isSelected ?? false)}
                    {!renderItem && (
                        <div className={cnTrackerSelect('list-item-content')}>
                            <span
                                className={cnTrackerSelect('list-item-text')}
                                ref={handleTextNodeRef}
                            >
                                {item.display}
                            </span>
                            {withMeta && (
                                <span className={cnTrackerSelect('list-item-meta')}>
                                    {item.meta}
                                </span>
                            )}
                        </div>
                    )}
                </div>
                {(ItemActions || pinnable) && (
                    <div className={cnTrackerSelect('list-item-actions')}>
                        {ItemActions && <ItemActions item={item} />}
                        {pinnable && (
                            <Button
                                view="flat-secondary"
                                size="m"
                                className={cnTrackerSelect('list-item-action', {type: 'pin'})}
                                onClick={handlePinClick}
                            >
                                <Icon data={item.pinned ? PinSlash : Pin} />
                            </Button>
                        )}
                    </div>
                )}
                {renderInfo && (
                    <div className={cnTrackerSelect('list-item-info')}>
                        {renderInfo(item, isSelected ?? false)}
                    </div>
                )}
            </div>
        </Tooltip>
    );
};

export const SelectItem = memo(SelectItemWrapped) as typeof SelectItemWrapped;
